"use strict";(globalThis.webpackChunkdocs_site=globalThis.webpackChunkdocs_site||[]).push([[3568],{4857(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"tutorialSidebar":[{"type":"link","href":"/GradCore-Tensor/docs/Intro","label":"Introduction","docId":"Intro","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/Getting Started","label":"Getting Started","docId":"Getting Started","unlisted":false},{"type":"category","label":"Tutorials","collapsible":true,"collapsed":false,"items":[{"type":"link","href":"/GradCore-Tensor/docs/tutorials/tutorial-1-california-housing","label":"Tutorial 1: California Housing Regression","docId":"tutorials/tutorial-1-california-housing","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/tutorials/tutorial-2-mnist","label":"Tutorial 2: MNIST Digit Classification","docId":"tutorials/tutorial-2-mnist","unlisted":false}],"href":"/GradCore-Tensor/docs/category/tutorials"},{"type":"category","label":"nn Module","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/nn_module/","label":"nn Module Overview","docId":"nn_module/index","unlisted":false},{"type":"category","label":"Core","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/nn_module/core/module","label":"Module","docId":"nn_module/core/module","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/nn_module/core/sequential","label":"Sequential","docId":"nn_module/core/sequential","unlisted":false}],"href":"/GradCore-Tensor/docs/category/core"},{"type":"category","label":"Layers","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/nn_module/layers/linear","label":"Linear","docId":"nn_module/layers/linear","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/nn_module/layers/activations","label":"Activation Layers","docId":"nn_module/layers/activations","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/nn_module/layers/batchnorm","label":"BatchNorm","docId":"nn_module/layers/batchnorm","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/nn_module/layers/dropout","label":"Dropout","docId":"nn_module/layers/dropout","unlisted":false}],"href":"/GradCore-Tensor/docs/category/layers"},{"type":"category","label":"Losses","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/nn_module/losses/overview","label":"Loss Functions","docId":"nn_module/losses/overview","unlisted":false}],"href":"/GradCore-Tensor/docs/category/losses"},{"type":"category","label":"Data","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/nn_module/data/dataset","label":"Dataset","docId":"nn_module/data/dataset","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/nn_module/data/dataloader","label":"DataLoader","docId":"nn_module/data/dataloader","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/nn_module/data/csv_loader","label":"CSVLoader","docId":"nn_module/data/csv_loader","unlisted":false}],"href":"/GradCore-Tensor/docs/category/data"},{"type":"category","label":"Training","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/nn_module/training/trainer","label":"Trainer","docId":"nn_module/training/trainer","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/nn_module/training/training_stats","label":"TrainingStats","docId":"nn_module/training/training_stats","unlisted":false}],"href":"/GradCore-Tensor/docs/category/training"},{"type":"category","label":"Models","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/nn_module/models/model","label":"Model","docId":"nn_module/models/model","unlisted":false}],"href":"/GradCore-Tensor/docs/category/models"},{"type":"category","label":"Utils","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/nn_module/utils/initialization","label":"Initialization","docId":"nn_module/utils/initialization","unlisted":false}],"href":"/GradCore-Tensor/docs/category/utils"}],"href":"/GradCore-Tensor/docs/category/nn-module"},{"type":"category","label":"Tensor Module","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/","label":"Tensor Module Overview","docId":"tensor_module/index","unlisted":false},{"type":"category","label":"Memory","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/memory/arena","label":"Arena Allocator","docId":"tensor_module/memory/arena","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/memory/platform","label":"Platform Layer","docId":"tensor_module/memory/platform","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/memory/prng","label":"PRNG","docId":"tensor_module/memory/prng","unlisted":false}],"href":"/GradCore-Tensor/docs/category/memory"},{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/tensor-basics","label":"Tensor Basics","docId":"tensor_module/tensor-basics","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/tensor-views","label":"Tensor Views","docId":"tensor_module/tensor-views","unlisted":false},{"type":"category","label":"Arithmetic","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/arithmetic/overview","label":"Arithmetic Operations","docId":"tensor_module/arithmetic/overview","unlisted":false}],"href":"/GradCore-Tensor/docs/category/arithmetic"},{"type":"category","label":"Activations","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/activations/overview","label":"Activation Functions","docId":"tensor_module/activations/overview","unlisted":false}],"href":"/GradCore-Tensor/docs/category/activations"},{"type":"category","label":"Loss Functions","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/loss_functions/overview","label":"Loss Functions","docId":"tensor_module/loss_functions/overview","unlisted":false},{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/loss_functions/reduction-modes","label":"Reduction Modes","docId":"tensor_module/loss_functions/reduction-modes","unlisted":false}],"href":"/GradCore-Tensor/docs/category/loss-functions"},{"type":"link","href":"/GradCore-Tensor/docs/tensor_module/autograd-integration","label":"Tensors in the Autograd Engine","docId":"tensor_module/autograd-integration","unlisted":false}],"href":"/GradCore-Tensor/docs/category/tensor-module"}]},"docs":{"Getting Started":{"id":"Getting Started","title":"Getting Started","description":"Getting Started","sidebar":"tutorialSidebar"},"Intro":{"id":"Intro","title":"Introduction","description":"GradCore-Tensor is a compact, high-performance C++ library for building, training, and running neural networks with an API inspired by PyTorch. It provides a clear, object-oriented implementation of tensors, an autograd engine, neural network building blocks, optimizers, and a lightweight data pipeline \u2014 all implemented from first principles so you can read, understand, and extend every part of the stack.","sidebar":"tutorialSidebar"},"nn_module/core/module":{"id":"nn_module/core/module","title":"Module","description":"Module is the abstract base class for every layer, activation, loss, and container in GradCore-Tensor. If you want to write a custom layer, you subclass Module. If you want to understand how a layer works internally, you understand Module first.","sidebar":"tutorialSidebar"},"nn_module/core/sequential":{"id":"nn_module/core/sequential","title":"Sequential","description":"Sequential is a Module that holds an ordered list of child modules and runs them one after another during forward(). The output of layer N is fed directly as input to layer N+1. That\'s it. Simple, composable, and the backbone of every model in GradCore-Tensor.","sidebar":"tutorialSidebar"},"nn_module/data/csv_loader":{"id":"nn_module/data/csv_loader","title":"CSVLoader","description":"CSVLoader is a static utility class for loading, parsing, and preprocessing tabular data from CSV files. It handles the entire pipeline from raw file to training-ready vectors \u2014 no external libraries, no Python dependency, no nonsense.","sidebar":"tutorialSidebar"},"nn_module/data/dataloader":{"id":"nn_module/data/dataloader","title":"DataLoader","description":"DataLoader slices a Dataset into mini-batches, optionally shuffles the sample order at the start of each epoch, and hands them to the training loop one batch at a time.","sidebar":"tutorialSidebar"},"nn_module/data/dataset":{"id":"nn_module/data/dataset","title":"Dataset","description":"Dataset is a thin wrapper that takes a block of float data (e.g. your training features or labels), stores it on the permanent arena, and exposes a shape-aware interface for DataLoader to batch from.","sidebar":"tutorialSidebar"},"nn_module/index":{"id":"nn_module/index","title":"nn Module Overview","description":"The nn module is the primary interface for building, training, and running neural networks in GradCore-Tensor. If the Tensor Module is the engine room, nn is the bridge \u2014 you issue commands here, and the lower layers handle all the mechanics.","sidebar":"tutorialSidebar"},"nn_module/layers/activations":{"id":"nn_module/layers/activations","title":"Activation Layers","description":"Activation layers are thin nn::* activation functions. They hold no parameters and no state \u2014 their only job is to sit in a Sequential and call the right autograd op when forward() is invoked.","sidebar":"tutorialSidebar"},"nn_module/layers/batchnorm":{"id":"nn_module/layers/batchnorm","title":"BatchNorm","description":"Batch Normalisation normalises a layer\'s inputs across the batch dimension, then rescales and shifts with learned parameters. The result is faster training, reduced sensitivity to initialisation, and a mild regularisation effect \u2014 which is a very good return on investment for two extra tensors.","sidebar":"tutorialSidebar"},"nn_module/layers/dropout":{"id":"nn_module/layers/dropout","title":"Dropout","description":"Dropout randomly zeroes out a fraction of activations during training. Each element is independently set to zero with probability p, and the surviving elements are scaled up by 1/(1-p) to keep the expected sum the same. During evaluation, dropout is a complete no-op \u2014 every neuron is active.","sidebar":"tutorialSidebar"},"nn_module/layers/linear":{"id":"nn_module/layers/linear","title":"Linear","description":"The fully-connected layer. Takes an input of shape [batch, infeatures], multiplies by a weight matrix, optionally adds a bias, and produces output of shape [batch, outfeatures].","sidebar":"tutorialSidebar"},"nn_module/losses/overview":{"id":"nn_module/losses/overview","title":"Loss Functions","description":"The nn loss classes are the user-facing wrappers over the tensor-level tensor*loss functions. They inherit from LossFunction, hold a Reduction mode, and expose a single forward() method. They also work as callables via operator().","sidebar":"tutorialSidebar"},"nn_module/models/model":{"id":"nn_module/models/model","title":"Model","description":"Model is the top-level object you interact with when building and training networks in GradCore-Tensor. It owns a Sequential container, wires together an optimizer and loss function, and exposes a Keras-style interface: compile then train then evaluate.","sidebar":"tutorialSidebar"},"nn_module/training/trainer":{"id":"nn_module/training/trainer","title":"Trainer","description":"Trainer is the training loop engine. It owns no model weights \u2014 it receives a Module*, an optimizer, a loss function, and a graph arena, then runs the forward \u2192 loss \u2192 backward \u2192 step cycle for as many epochs as you ask for.","sidebar":"tutorialSidebar"},"nn_module/training/training_stats":{"id":"nn_module/training/training_stats","title":"TrainingStats","description":"TrainingStats is a plain data struct returned by Trainer::fit_dataloader at the end of a training run. It gives you a record of how the loss evolved over every epoch, plus a few headline numbers.","sidebar":"tutorialSidebar"},"nn_module/utils/initialization":{"id":"nn_module/utils/initialization","title":"Initialization","description":"Good weight initialisation is not optional \u2014 initialise too small and gradients vanish, too large and they explode. The functions in nn::init give you the standard schemes that the deep learning literature has converged on over the past decade.","sidebar":"tutorialSidebar"},"tensor_module/activations/overview":{"id":"tensor_module/activations/overview","title":"Activation Functions","description":"Activation functions introduce non-linearity into your network. Without them, a 47-layer neural network would have the expressive power of a single matrix multiply \u2014 and we\'d all be out of a hobby.","sidebar":"tutorialSidebar"},"tensor_module/arithmetic/overview":{"id":"tensor_module/arithmetic/overview","title":"Arithmetic Operations","description":"These are the low-level tensor math functions. Every layer in GradCore-Tensor ultimately calls one or more of these. They all follow the same conventions:","sidebar":"tutorialSidebar"},"tensor_module/autograd-integration":{"id":"tensor_module/autograd-integration","title":"Tensors in the Autograd Engine","description":"The tensor module provides the data. The autograd engine provides the memory of what you did with that data \u2014 so it can run the chain rule backwards. Here\'s how the two connect.","sidebar":"tutorialSidebar"},"tensor_module/index":{"id":"tensor_module/index","title":"Tensor Module Overview","description":"Welcome to the nerve centre of GradCore-Tensor. Everything \u2014 training, inference, backprop, your optimizer quietly panicking about learning rates \u2014 ultimately comes down to operations on Tensor objects. This section documents every corner of the tensor module so you know exactly what\'s happening under the hood.","sidebar":"tutorialSidebar"},"tensor_module/loss_functions/overview":{"id":"tensor_module/loss_functions/overview","title":"Loss Functions","description":"A loss function measures how wrong your model is. Training is the process of making it less wrong, one gradient at a time. Choosing the right loss function is not optional \u2014 using MSE for a classification problem is like using a ruler to measure temperature.","sidebar":"tutorialSidebar"},"tensor_module/loss_functions/reduction-modes":{"id":"tensor_module/loss_functions/reduction-modes","title":"Reduction Modes","description":"Reduction modes control whether a loss function returns a per-element tensor or collapses to a scalar. Every loss function in GradCore-Tensor accepts a Reduction argument.","sidebar":"tutorialSidebar"},"tensor_module/memory/arena":{"id":"tensor_module/memory/arena","title":"Arena Allocator","description":"The Arena is GradCore-Tensor\'s memory backbone. If you\'ve ever watched a neural network training session grind to a halt because malloc decided it was a great time to coalesce free blocks, you\'ll appreciate what an arena allocator does for you: it doesn\'t bother with any of that.","sidebar":"tutorialSidebar"},"tensor_module/memory/platform":{"id":"tensor_module/memory/platform","title":"Platform Layer","description":"platform.hpp is a thin wrapper around OS-level operations: virtual memory management and entropy generation. All the gritty mmap/munmap/mprotect calls live here so the rest of the codebase stays clean and portable (in theory \u2014 in practice it\'s Linux only, as the Introduction honestly admits).","sidebar":"tutorialSidebar"},"tensor_module/memory/prng":{"id":"tensor_module/memory/prng","title":"PRNG","description":"GradCore-Tensor uses a PCG (Permuted Congruential Generator) for all random number generation. PCG is fast, has excellent statistical properties, and produces 32 bits of randomness per step \u2014 which is exactly what you need for weight initialisation and data shuffling, and absolutely overkill for anything that doesn\'t need cryptographic security (which is everything in a neural network training loop).","sidebar":"tutorialSidebar"},"tensor_module/tensor-basics":{"id":"tensor_module/tensor-basics","title":"Tensor Basics","description":"The Tensor struct is the central data structure in GradCore-Tensor. It describes a multi-dimensional array of float values and knows how to index into them correctly, whether the data is contiguous in memory or is a strided view of something else.","sidebar":"tutorialSidebar"},"tensor_module/tensor-views":{"id":"tensor_module/tensor-views","title":"Tensor Views","description":"Views are tensors that share memory with another tensor. Changing the data through a view changes the original, and vice versa \u2014 because they\'re the same bytes, just described differently.","sidebar":"tutorialSidebar"},"tutorials/tutorial-1-california-housing":{"id":"tutorials/tutorial-1-california-housing","title":"Tutorial 1: California Housing Regression","description":"This tutorial walks through the California Housing dataset regression example end-to-end \u2014 from loading CSV data to running inference on unseen samples. By the end you will understand how CSVLoader, nn::Model, and the training loop fit together.","sidebar":"tutorialSidebar"},"tutorials/tutorial-2-mnist":{"id":"tutorials/tutorial-2-mnist","title":"Tutorial 2: MNIST Digit Classification","description":"This tutorial covers multi-class image classification using the MNIST handwritten digit dataset. You will learn how to set up batched loading with DataLoader, build a classifier, train with CrossEntropyLoss, evaluate test accuracy, and run per-sample inference with a visual terminal display.","sidebar":"tutorialSidebar"}}}}')}}]);